request.body:
config-version: 8
server: {host: 127.0.0.1, port: 38922}
management: {allow-remote: false, secret-key: e2e-mgmt-secret, disable-control-panel: true}
access:
  api-keys: [e2e-client-key]
oauth:
  auth-dir: "{{AUTH_DIR}}"
  providers:
    claude: {header-defaults: {timezone: "Asia/Shanghai", user-agent: claude-cli/1.0}, model-level-cooling: true}
    xai: {inject-x-search: false}
